 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
        await $c.win.alert(trs_Save.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30000_POP.trs_Save_OnFail" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name save
 * @description 저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    let conYN = "Y"; // 확정여부  확인
    let reYN = "Y"; // 진행여부 확인

    // alert("dts_List.CountRow-->"+dts_List.CountRow);

    // 확정 체크
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        // alert("확정여부-->"+dts_List.NameValue(i, "TOTAL_SCHDL_CONFRM_YN")+"---"+ i );
        if (dts_List.getCellData(i, "TOTAL_SCHDL_CONFRM_YN") === "N") {
            conYN = "N";
            await $c.win.alert("담당자 확인이 되지 않은 일정이 있습니다.\n담당자 확인을 먼저 해주시기 바랍니다.");
            await $c.win.closePopup();
            return false;
        } else {
            conYN = "Y";
        }
    }

    // 책임자 또는 당번이 마감을 할 경우 담당자 또는 팀이 마감이 안되어 있을때 본인(책임자,당번)이 마감을 못하도록 막는다.
    // 당번 마감은 모든 공시팀이 마감을 했을 경우에 가능
    // 책임자 마감은 해당 팀 담당자가 모두 마감을 했을 경우에 가능.
    if (dts_List.getRowCount() > 1) {
        for (let i = 2; i <= dts_List.getRowCount(); i++) {
            // alert("CLS_YN-->"+dts_List.NameValue(i, "CLS_YN")+"---"+ i );
            if (dts_List.getCellData(i, "CLS_YN") === "N") {
                reYN = "N";
                await $c.win.alert("진행중인 담당자 또는 팀이 있습니다.\n진행건을 먼저 마감 해주시기 바랍니다.");
                return false;
            }
        }
    }
    if (conYN === "Y") {
        if (reYN === "Y") {
            const res = window.confirm("[저장]하시겠습니까?");
            if (res) {
                trs_Save.KeyName = "toinb_dataid4";
                const sbmOptions = {
                    id : "sbm_trs_Save",
                    action : "/DisclosureSchedule.do",
                    ref : "dts_List",
                    target : "trs_Save=body.content",
                    isProcessMsg : false
                };

                const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
            }
        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listSync
 * @description 데이타 가져와서 뿌리기 List
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    const url = "/DisclosureSchedule.do?method=listScheduleClose";
    scwin.url += "&EMP_NO=" + js_emp_no; // 사원번호
    scwin.url += "&BELNG_DEP_CD=" + js_belngdepcd; // 상위부서코드
    scwin.url += "&DEP_CD=" + js_dep_cd; // 부서코드
    scwin.url += "&SCREN_ID=" + "ULDSTF30000_POP.xml";
    scwin.url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 코스닥당번이면
    if (js_duty === "Y" || js_duty_chrg === "Y") {
        // if(js_emp_no == "adm040"){
        scwin.url += "&DUTY=Y"; // 당번여부 (Y, N)

    } else {
        scwin.url += "&DUTY=N"; // 당번여부 (Y, N)

    }
    scwin.url += "&JOB_TITLE=" + js_jobtitl; // 직책구분 여부 - 03:담당자, 09:책임자
    scwin.url += "&TODATE=" + $c.ut.cGetToday2(); // 날짜
    // url += "&TODATE=20090901" ;                    //날짜

    dts_List.DataID = encodeURI(scwin.url);
    dts_List.reset();
};

