/**
 * @method
 * @name chkClick
 * @description 콤보의 변경전 값을 저장
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.chkClick = function(row, colid) {
    scwin.chk = dts_List.getCellData(row, colid);
};

